using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer accepts navigation or
        // computed properties with non-constant values. Use a fixed seed value.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---
class CosmosDbContext : DbContext
{
    public DbSet<Document> Documents => Set<Document>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "EfAppDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: Cosmos provider now uses "Discriminator" (capital D)
        // by default instead of "$type". For existing documents that already store
        // "Discriminator", this is compatible. If your documents used a DIFFERENT
        // property name, you must configure it explicitly:
        // modelBuilder.Entity<Document>().HasDiscriminator<string>("YourPropertyName");

        modelBuilder.Entity<Document>().ToContainer("Documents");
        modelBuilder.Entity<Document>().HasPartitionKey(d => d.PartitionKey);
    }
}

class Document
{
    public string Id { get; set; } = null!;
    public string PartitionKey { get; set; } = null!;
    public string Title { get; set; } = null!;
}

// --- Cosmos query service demonstrating sync→async migration ---
class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // EF Core 9 breaking change: Synchronous I/O is no longer supported
    // on the Cosmos DB provider. All queries must use async methods.
    // Before (EF Core 8):  _db.Documents.ToList()
    // After  (EF Core 9):  await _db.Documents.ToListAsync()
    public async Task<List<Document>> GetDocumentsAsync()
    {
        return await _db.Documents.ToListAsync();
    }

    public async Task<Document?> FindDocumentAsync(string id)
    {
        // Before: _db.Documents.FirstOrDefault(d => d.Id == id)
        return await _db.Documents.FirstOrDefaultAsync(d => d.Id == id);
    }
}

